def maxStrength (nums : List Int) (h_precond : maxStrength_precond (nums)) : Int :=
  let filterNeg := nums.filter (· < 0)
  let negCount := filterNeg.length
  let nonNeg := nums.filter (· >= 0)
  let maxNonNeg := nonNeg.foldl (· * ·) 1
  let maxProd := if negCount % 2 = 0 then maxNonNeg else if nonNeg.length = 0 then if nums.contains 0 then 0 else -1 else maxNonNeg
  maxProd
